"""Half-open integer interval operations."""


def _clean(intervals):
    """Filter out empty intervals (start >= end)."""
    return [(s, e) for (s, e) in intervals if s < e]


def merge(intervals):
    """Merge overlapping and touching half-open intervals."""
    ivs = sorted(_clean(intervals))
    if not ivs:
        return []
    out = [list(ivs[0])]
    for s, e in ivs[1:]:
        if s <= out[-1][1]:
            if e > out[-1][1]:
                out[-1][1] = e
        else:
            out.append([s, e])
    return [(s, e) for s, e in out]


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    clipped = []
    for s, e in _clean(intervals):
        cs, ce = max(s, ws), min(e, we)
        if cs < ce:
            clipped.append((cs, ce))
    covered = merge(clipped)
    gaps = []
    cur = ws
    for s, e in covered:
        if s > cur:
            gaps.append((cur, s))
        cur = max(cur, e)
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point."""
    events = []
    for s, e in _clean(intervals):
        events.append((s, 1))
        events.append((e, -1))
    # Sort so that at equal positions, starts are processed before ends,
    # which is correct for half-open intervals: (1,3) and (3,5) do not overlap.
    events.sort()
    best = cur = 0
    for _, delta in events:
        cur += delta
        if cur > best:
            best = cur
    return best

"""LRU cache with per-entry time-to-live."""

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._clock = clock
        # key -> [value, expires_at or None]
        self._entries = OrderedDict()

    def _purge_expired(self):
        now = self._clock()
        dead = [k for k, (v, exp) in self._entries.items()
                if exp is not None and now >= exp]
        for k in dead:
            del self._entries[k]
        return len(dead)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self._clock()
        if key in self._entries:
            self._entries.move_to_end(key)
        else:
            if len(self._entries) >= self._capacity:
                self._purge_expired()
                if len(self._entries) >= self._capacity:
                    self._entries.popitem(last=False)
        exp = None if ttl is None else now + ttl
        self._entries[key] = [value, exp]

    def get(self, key, default=None):
        if key not in self._entries:
            return default
        value, exp = self._entries[key]
        if exp is not None and self._clock() >= exp:
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        if key not in self._entries:
            return False
        _, exp = self._entries[key]
        if exp is not None and self._clock() >= exp:
            del self._entries[key]
            return False
        return True

    def __len__(self):
        return self._purge_expired()

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()


